const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
function currentEmployee() { return state.employees.find(employee => employee.id === state.activeEmployeeId) || state.employees[0] || defaultEmployees[0]; }
function currentRole() { const employee = currentEmployee(); return state.roles.find(role => role.id === employee.roleId) || state.roles.find(role => role.id === 'role-owner') || defaultRoles[0]; }
function hasPermission(permission) { return (currentRole().permissions || []).includes(permission); }
function saveRolesAndEmployees() { localStorage.setItem('verdi-roles-v1', JSON.stringify(state.roles)); localStorage.setItem('verdi-employees-v1', JSON.stringify(state.employees)); }
function initials(name = '') { return String(name).trim().split(/\s+/).slice(0, 2).map(part => part[0] || '').join('').toUpperCase() || 'VT'; }
function accessibleViews() { return ['dashboard', 'projects', 'leads', 'team'].filter(view => view === 'team' ? hasPermission('team') : hasPermission(view)); }

