function saveLeads() { localStorage.setItem('verdi-leads-v1', JSON.stringify(state.leads)); }
function leadNicheKey(lead) {
  const niche = `${lead?.segment || ''} ${lead?.company || ''}`.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (/carro|automovel|veiculo|concessionaria|revenda/.test(niche)) return 'cars';
  if (/construc|materia|obra|ferragem/.test(niche)) return 'construction';
  if (/roupa|moda|vestu|confecc|boutique/.test(niche)) return 'clothing';
  if (/mecan|oficina|auto.?center/.test(niche)) return 'mechanic';
  if (/restaurante|lanchonete|pizzaria|cafeteria/.test(niche)) return 'restaurant';
  if (/barbear/.test(niche)) return 'barber';
  if (/clinica|odont/.test(niche)) return 'clinic';
  return 'first';
}
